# Impure: mutates the caller's cart and reads the clock
def add_item(cart, item):
    item["added_at"] = datetime.now()
    cart.append(item)
    return sum(i["price"] for i in cart)

# Pure core: same inputs, same output, nothing touched
def cart_total(items):
    return sum(item["price"] for item in items)

def with_item(items, item, added_at):
    return [*items, {**item, "added_at": added_at}]

# Thin shell: the side effects live here, in plain sight
def add_to_cart(cart_repo, user_id, item):
    items = cart_repo.load(user_id)
    updated = with_item(items, item, added_at=datetime.now())
    cart_repo.save(user_id, updated)
    return cart_total(updated)

