# Swallowed: the failure vanishes and the user is told "saved"
def save_profile(user_id, changes):
    try:
        db.update("profiles", user_id, changes)
    except Exception:
        pass
    return "saved"

# Handled: fail fast, catch narrowly, wrap with context
class ProfileSaveError(Exception):
    pass

def save_profile(user_id, changes):
    if not changes:
        raise ValueError(f"no changes given for profile {user_id}")
    try:
        db.update("profiles", user_id, changes)
    except db.ConnectionError as err:
        raise ProfileSaveError(f"profile {user_id} was not saved") from err
    return "saved"

# Before: magic number, nested ifs, the clock read inside
def can_refund(o):
    if o.status == "shipped" or o.status == "delivered":
        if (date.today() - o.placed_on).days <= 30:
            if o.total_cents > 0:
                return True
    return False

# After: named constants, one guard, today passed in
REFUND_WINDOW_DAYS = 30
REFUNDABLE_STATUSES = {"shipped", "delivered"}

def can_refund(order, today):
    if order.status not in REFUNDABLE_STATUSES:
        return False
    days_since_order = (today - order.placed_on).days
    return days_since_order <= REFUND_WINDOW_DAYS and order.total_cents > 0

